import pytest

from corrected_calcium import corrected_calcium, classify


class TestCorrectedCalcium:
    def test_hand_checked_example(self):
        # Ca 7.8 + 0.8 * (4.0 - 2.0) = 7.8 + 1.6 = 9.4
        assert corrected_calcium(7.8, 2.0) == pytest.approx(9.4)

    def test_no_correction_at_albumin_4(self):
        assert corrected_calcium(9.0, 4.0) == 9.0

    def test_no_correction_above_albumin_4(self):
        assert corrected_calcium(11.2, 5.0) == 11.2

    def test_correction_below_albumin_4(self):
        # 8.0 + 0.8 * (4.0 - 3.5) = 8.4
        assert corrected_calcium(8.0, 3.5) == pytest.approx(8.4)

    def test_boundary_lowest_valid_inputs(self):
        # 4.0 + 0.8 * (4.0 - 0.5) = 6.8
        assert corrected_calcium(4.0, 0.5) == pytest.approx(6.8)

    def test_boundary_highest_valid_inputs(self):
        # Albumin at max -> no correction
        assert corrected_calcium(18.0, 6.0) == 18.0

    def test_calcium_too_low_raises(self):
        with pytest.raises(ValueError, match="calcium"):
            corrected_calcium(3.99, 4.0)

    def test_calcium_too_high_raises(self):
        with pytest.raises(ValueError, match="calcium"):
            corrected_calcium(18.01, 4.0)

    def test_albumin_too_low_raises(self):
        with pytest.raises(ValueError, match="albumin"):
            corrected_calcium(9.0, 0.49)

    def test_albumin_too_high_raises(self):
        with pytest.raises(ValueError, match="albumin"):
            corrected_calcium(9.0, 6.01)


class TestClassify:
    @pytest.mark.parametrize(
        "value,expected",
        [
            (8.49, "low"),
            (8.5, "normal"),      # exact lower boundary
            (9.4, "normal"),
            (10.5, "normal"),     # exact upper boundary
            (10.51, "high"),
        ],
    )
    def test_classify_boundaries(self, value, expected):
        assert classify(value) == expected

